UA="Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36"
for H in 440366 ad8280 3004c7; do mkdir -p $H; for b in $(seq 1 225); do d=$(date -u -d "2026-09-30 -$b day" +%Y/%m/%d); f=$H/$(echo $d | tr / -).json; [ -e $f ] || [ -e $f.404 ] && continue; if [ $b -le 40 ]; then u="https://adsb.lol/globe_history/$d/traces/${H: -2}/trace_full_$H.json"; else u="https://globe.airplanes.live/globe_history/$d/traces/${H: -2}/trace_full_$H.json"; fi; c=$(curl -s -m 30 -A "$UA" --compressed -o $f -w "%{http_code}" "$u"); if [ "$c" != "200" ]; then rm -f $f; touch $f.404; fi; sleep 0.15; done; echo $H $(ls $H | grep -v 404 | wc -l) days; done
